function entries(course){return course.videos.flatMap(v=>(db.meta[v.bvid]?.pages||[]).map(p=>({bvid:v.bvid,p:p.page,cid:p.cid,title:p.part,duration:p.duration,key:key(v.bvid,p.page)})));}
function fraction(e){const s=state(e.key);return s.lock!==null ? (s.lock?1:0) : s.done?1:clamp(s.position/e.duration);}
function percent(list){const total=list.reduce((a,e)=>a+e.duration,0);return total?list.reduce((a,e)=>a+e.duration*fraction(e),0)/total:0;}
