const $=s=>root.querySelector(s);function status(s){$('#status').textContent=s;}let toastTimer;function toast(t){$('.toast').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('.toast').textContent='',4500);}
let official=false;const pageStyle=document.createElement('style');document.head.append(pageStyle);
function applyStyle(){
 const playback=/\/video\/BV[0-9A-Za-z]{10}/.test(location.pathname);
 // Overlay mode never changes body padding, widths, transforms or horizontal scroll.
 pageStyle.textContent=official?'':`${home?'body > *:not(#orange-classroom){visibility:hidden!important}':''} ${playback?`
 #biliMainHeader,.bili-header,.bili-header__bar,.international-header,.mini-header{display:none!important}
 #comment,#commentapp,.comment-container,.comment-container-v1,.video-comments,bili-comments,.video-desc-container,.video-desc,.video-tag-container,.tag-container{display:none!important}
 .recommend-list-v1,.rec-list,.recommend-container,.recommend-video,.video-recommend,.recommend-list,.bpx-player-ending-related,.bpx-player-ending-recommend{display:none!important}
 .ad-report,.ad-report-inner,.ad-floor-exp,.ad-floor-cover,.video-page-game-card-small,.video-page-special-card-small,.slide-ad-exp,.banner-card,.activity-banner,.activity-m-v1,.activity-m,.pop-live-small-mode{display:none!important}
 a[href*="cm.bilibili.com"],a[href*="b23.tv/mall"],iframe[src*="cm.bilibili.com"]{display:none!important}
 `:''}`;
}
function viewport(){const v=window.visualViewport;return {x:v?.offsetLeft||0,y:v?.offsetTop||0,w:v?.width||innerWidth,h:v?.height||innerHeight};}
function locate(el,k){const v=viewport(),r=el.getBoundingClientRect(),saved=db.ui.positions[positionKey(k)];const x=clamp(saved?.x??(v.w-r.width-14),4,Math.max(4,v.w-r.width-4)),y=clamp(saved?.y??(k==='closed'?18:70),4,Math.max(4,v.h-r.height-4));el.style.right='auto';el.style.bottom='auto';el.style.left=(x+v.x)+'px';el.style.top=(y+v.y)+'px';}
function setMode(next,persist=true){mode=next;$('.panel').hidden=home||mode!=='full';$('.mini').hidden=home||mode!=='mini';$('#toggle').hidden=!home&&mode!=='closed';if(persist){db.ui.mode=next;save();}requestAnimationFrame(()=>{if(!$('.panel').hidden)locate($('.panel'),'full');if(!$('.mini').hidden)locate($('.mini'),'mini');if(!$('#toggle').hidden)locate($('#toggle'),'closed');});}
function panel(on){home=false;$('.home').hidden=true;official=false;setMode(on?'full':'closed');applyStyle();renderList(true);}
let authState='checking',authRequest=null,loginPoll=0,loginOpen=false;
function authLabel(){return {checking:'正在检查登录…',guest:'去登录 B 站',member:'已登录 B 站',error:'登录状态检测失败 · 点此重试'}[authState];}
function updateAuthControls(){
 const allowed=authState==='member';
 for(const button of root.querySelectorAll('[data-act="fromUp"],[data-from-up],[data-m="source"],[data-m="sourceLoad"]')){
  button.disabled=!allowed||(button.dataset.m==='sourceLoad'&&(source?.busy||source?.done));
  button.title=allowed?'':'请先登录 B 站再读取 UP 主投稿';
 }
 for(const button of root.querySelectorAll('[data-auth], [data-act="official"], #official')){
  button.textContent=authLabel();button.disabled=authState==='checking'||allowed;
 }
 for(const note of root.querySelectorAll('[data-login-note]'))note.textContent=allowed?'':authState==='guest'?'请先登录 B 站，才能从 UP 主添加视频。':authLabel();
}
function checkLogin(){
 if(authRequest)return authRequest;
 authRequest=(async()=>{
  try{const nav=await jsonRequest('/x/web-interface/nav');
   if(nav.code===0&&nav.data?.isLogin===true){authState='member';const img=nav.data.wbi_img;if(img)wbiKey=signingKey(img);}
   else if(nav.code===-101||nav.data?.isLogin===false){authState='guest';wbiKey='';}
   else authState='error';
  }catch{authState='error';}finally{authRequest=null;updateAuthControls();}
  return authState;
 })();return authRequest;
}
function openHomepageLogin(){
 if(loginOpen)return;
 loginOpen=true;
 const html=document.documentElement;
 html.setAttribute('data-lemon-login','');
 const sheet=document.createElement('style');
 sheet.textContent=`
 html[data-lemon-login],html[data-lemon-login] body{background:#fafbf5!important}
 html[data-lemon-login] :is(#orange-classroom,.orange-touch-player,.bili-header__banner,.bili-banner,.bili-header__channel,.bili-layout,.bili-feed4-layout,.recommended-container_floor-aside,.feed-roll-btn,.palette-button-wrap,.bili-footer,.ad-report,.ad-floor-exp):not(:has(.bili-header__bar,.header-login-entry,.login-entry)){display:none!important}
 html[data-lemon-login] :is(.bili-header__bar,.international-header .mini-header__content){background:#fff!important;background-image:none!important}
 html[data-lemon-login] :is(.left-entry,.center-search-container,.nav-search-box,.nav-search-form,.mini-header__title,.nav-link-ul,.right-entry__outside:not(.header-login-entry,.login-entry):not(:has(.header-login-entry,.login-entry,.header-login-entry__button)),.right-entry__outside-btn:not(.header-login-entry,.login-entry),.header-upload-entry,.header-message-entry,.header-dynamic-entry,.header-favorite-entry,.header-history-entry,.upload-entry){visibility:hidden!important;pointer-events:none!important}
 html[data-lemon-login] :is(.left-entry,.nav-link-ul,.center-search-container) :is(a,button,input){visibility:hidden!important;pointer-events:none!important}
 `;
 document.head.append(sheet);
 // Release the classroom homepage veil; official overlays can now render anywhere.
 official=true;applyStyle();
 const back=document.createElement('button');
 back.type='button';back.textContent='返回课堂';
 back.style.cssText='position:fixed;top:8px;left:8px;z-index:1000;min-height:44px;padding:8px 16px;border:1px solid #cdd6c8;border-radius:12px;background:#fafbf4;color:#29433b';
 html.append(back);
 function finish(){
  if(!loginOpen)return;
  loginOpen=false;clearInterval(loginPoll);
  location.replace(location.origin+'/');
 }
 back.onclick=finish;
 loginPoll=setInterval(async()=>{if(await checkLogin()==='member')finish();},3000);
}
async function loginAction(){
 if(authState==='error'){await checkLogin();if(authState!=='guest')return;}
 if(authState==='member'||loginOpen)return;
 if(!/^\/(?:zh-Hans\/?)?$/.test(location.pathname)){location.assign('https://www.bilibili.com/?lemon-login=1');return;}
 openHomepageLogin();
}
root.addEventListener('click',e=>{if(e.target.closest('[data-auth]'))loginAction();});
function authMarkup(){return '<small data-login-note></small><button data-auth>'+authLabel()+'</button>';}
function homepage(){home=true;official=false;$('.home').hidden=false;setMode(mode,false);renderHome();applyStyle();document.querySelectorAll('video').forEach(v=>v.pause());}
function drag(handle,el,k){let hold=null,suppress=false;handle.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('button')&&e.target.closest('button')!==handle)return;const r=el.getBoundingClientRect();hold={id:e.pointerId,x:e.clientX,y:e.clientY,left:r.left,top:r.top,moved:false};handle.setPointerCapture(e.pointerId);});handle.addEventListener('pointermove',e=>{if(!hold||e.pointerId!==hold.id)return;const dx=e.clientX-hold.x,dy=e.clientY-hold.y;if(Math.hypot(dx,dy)>6)hold.moved=true;if(!hold.moved)return;e.preventDefault();el.classList.add('dragging');const v=viewport(),r=el.getBoundingClientRect();const x=clamp(hold.left+dx-v.x,4,Math.max(4,v.w-r.width-4)),y=clamp(hold.top+dy-v.y,4,Math.max(4,v.h-r.height-4));el.style.left=(x+v.x)+'px';el.style.top=(y+v.y)+'px';db.ui.positions[positionKey(k)]={x,y};});const end=e=>{if(!hold||e.pointerId!==hold.id)return;suppress=hold.moved;hold=null;el.classList.remove('dragging');save();setTimeout(()=>suppress=false,350);};handle.addEventListener('pointerup',end);handle.addEventListener('pointercancel',end);handle.addEventListener('click',e=>{if(suppress){e.preventDefault();e.stopImmediatePropagation();suppress=false;}},true);}
drag($('#toggle'),$('#toggle'),'closed');drag($('.mini'),$('.mini'),'mini');drag($('.panel header'),$('.panel'),'full');
