// A fullscreen element hides DOM siblings regardless of their z-index.
// Keep the same live panel inside the fullscreen player, never clone it.
function fullscreenElement(){return document.fullscreenElement||document.webkitFullscreenElement;}
function positionKey(k){return (fullscreenElement()?'fullscreen:':'')+k;}
function syncFullscreenPanel(){
 const target=fullscreenElement();
 seekControls.hidden=!target;
 const parent=target&&!/^(VIDEO|IFRAME)$/.test(target.tagName)?target:document.documentElement;
 if(parent!==host&&host.parentNode!==parent)parent.append(host);
 setMode(mode,false);
}
for(const event of ['fullscreenchange','webkitfullscreenchange','fullscreenerror','webkitfullscreenerror'])document.addEventListener(event,syncFullscreenPanel);
for(const name of ['requestFullscreen','webkitRequestFullscreen','webkitRequestFullScreen']){
 const original=Element.prototype[name];if(typeof original!=='function')continue;
 Element.prototype[name]=function(...args){
  // Fullscreen the player container instead of the native video-only surface.
  const target=this.tagName==='VIDEO'?(this.closest('.bpx-player-container,.bilibili-player,#bilibili-player')||this.parentElement):this;
  if(!target||target===host||host.contains(target))return original.apply(this,args);
  target.append(host);
  try{const result=original.apply(target,args);if(result?.catch)return result.catch(error=>{syncFullscreenPanel();throw error;});return result;}
  catch(error){syncFullscreenPanel();throw error;}
 };
}
