async function action(a){if(a==='skins'){openSkins();return;}if(a==='goal'){openGoal();return;}if(a==='manage'){openManagement();return;}if(a==='fromUp'){openSource();return;}if(a==='official'){await loginAction();return;}if(a==='addUp'){const val=prompt('粘贴 UP 主空间链接或数字 UID（将加入允许名单）');if(!val)return;const id=val.trim().match(/^(?:https?:\/\/space\.bilibili\.com\/)?(\d+)(?:[/?].*)?$/)?.[1];if(!id)return toast('请填写空间链接或数字 UID');const name=prompt('给这位 UP 主起个显示名称');if(!name)return;if(!db.ups.some(u=>String(u.mid)===id))db.ups.push({mid:id,name});save();renderHome();return;}if(a==='addCourse'){const title=prompt('新合集名称');if(title?.trim()){db.courses.push({id:'course-'+Date.now(),title:title.trim(),videos:[]});save();renderHome();}return;}if(a==='add'){const input=prompt('粘贴 B站视频完整链接或 BV号（暂不支持 b23 短链接）');if(!input)return;const b=input.match(/BV[0-9A-Za-z]{10}/)?.[0];if(!b)return toast('没有找到 BV号，请使用完整视频链接');const pick=prompt('添加到哪个合集？输入编号\n'+db.courses.map((c,i)=>`${i+1}. ${c.title}`).join('\n'),'1');if(pick===null)return;const c=db.courses[Number(pick)-1];if(!c)return toast('合集编号无效');toast('正在读取课程…');try{const m=await metadata(b);if(!c.videos.some(v=>v.bvid===b))c.videos.push({bvid:b,title:m.title});save();renderHome();toast('课程已添加');}catch(e){toast(e.message);}return;}if(a==='export'&&typeof orangeExport==='function'){try{await orangeExport(JSON.stringify(db,null,2));toast('进度已导出');}catch(e){toast(e.message);}return;}if(a==='export'){const blob=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='lemon-classroom-progress.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),10000);return;}if(a==='import'){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const d=JSON.parse(await input.files[0].text());if(d.version!==1||!Array.isArray(d.courses)||!Array.isArray(d.ups)||!d.meta||!d.states||!d.cursor)throw Error('不是本脚本的进度文件');if(!confirm('导入将替换本浏览器的课程和进度，是否继续？'))return;if(d.rewards&&!LemonRewards.valid(d.rewards))throw Error('积分或皮肤数据格式不正确');db=d;save(true);location.reload();}catch(e){toast('导入失败：'+e.message);}};input.click();}}
