function sync(force=false){if(editFreeze&&active&&video){if(editFreeze.bvid===active.bvid&&editFreeze.p===active.p&&editFreeze.t===video.currentTime)return;editFreeze=null;}if(!active||!video||!Number.isFinite(video.duration)||video.duration<=0)return;const c=courseFor(active.bvid),m=db.meta[active.bvid],p=m?.pages.find(x=>x.page===active.p);if(!c||!p)return;/* Avoid applying the previous P's media time during a route transition. */if(Math.abs(video.duration-p.duration)>3){status('视频与目录时长不一致，暂停同步；请等待切 P 完成或重读目录');return;}if(!force&&video.currentTime===lastTime)return;lastTime=video.currentTime;follow(c,active.bvid,active.p,video.currentTime,video.ended||completedOnEnd);renderList();updateMetrics();if(Date.now()-lastSave>1500||force){save();lastSave=Date.now();}}
