async function checkRoute(){const match=location.pathname.match(/\/video\/(BV[0-9A-Za-z]{10})/),p=Math.max(1,Number(new URL(location.href).searchParams.get('p'))||1);const current=match?match[1]+':'+p+':'+(new URL(location.href).searchParams.get('oc_course')||''):location.pathname;if(current===route)return;route=current;const token=++routeVersion;bind(null);active=null;lastRender='';if(!match){if(/^\/(?:[a-z]{2}(?:-[A-Za-z]+)?\/?)?$/.test(location.pathname))homepage();return;}const b=match[1];status('读取课程…');try{const m=await metadata(b);if(token!==routeVersion)return;let c=courseFor(b);if(!c){c=db.courses[0];if(!c){c={id:'course-'+Date.now(),title:'我的课程',videos:[]};db.courses.push(c);}c.videos.push({bvid:b,title:m.title});save();}active={bvid:b,p};const remembered=mode;panel(true);setMode(remembered);await loadCourse(c);if(token!==routeVersion)return;renderList(true);}catch(e){if(token!==routeVersion)return;panel(true);status(e.message+'。可返回课程主页，或显示官方页面。');}}
